		n, _ := r.Body.Read(raw)
		seenBody = string(raw[:n])
		w.Header().Set("Set-Cookie", "collector=1")
		w.Header().Set("Content-Type", "application/javascript")
		w.WriteHeader(http.StatusAccepted)
		_, _ = w.Write([]byte("ok"))
	}))
	defer collector.Close()
	config := tracking.ReadConfig(map[string]any{
		"enabled": true, "provider": "momento", "allow_insecure_http": true,
		"momento_url": collector.URL + "/base/", "momento_site_id": "jikim",
	})
	server, handler := trackingServer(t, config, nil)
	server.httpClient = http.DefaultClient

	response := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodPost, "/momento/collect/v1/events", strings.NewReader(`{"e":1}`))
	request.Header.Set("Cookie", "jikim_session=secret")
	request.Header.Set("Authorization", "Bearer secret")
	handler.ServeHTTP(response, request)
	if response.Code != http.StatusAccepted || response.Body.String() != "ok" {
		t.Fatalf("status=%d body=%s", response.Code, response.Body.String())
	}
	if seenPath != "/base/collect/v1/events" || seenMethod != http.MethodPost || seenBody != `{"e":1}` {
		t.Fatalf("collector saw path=%s method=%s body=%s", seenPath, seenMethod, seenBody)
	}
	if seenCookie != "" {
		t.Fatalf("session cookie forwarded to the collector: %s", seenCookie)
	}
	if response.Header().Get("Set-Cookie") != "" {
		t.Fatal("collector cookie handed to the browser under our origin")
	}
	if response.Header().Get("Content-Security-Policy") != apiPolicy {
		t.Fatalf("proxy response policy=%q", response.Header().Get("Content-Security-Policy"))
	}

	denied := httptest.NewRecorder()
	handler.ServeHTTP(denied, httptest.NewRequest(http.MethodDelete, "/momento/collect", nil))
	if denied.Code != http.StatusMethodNotAllowed {
		t.Fatalf("DELETE through the proxy status=%d", denied.Code)
	}

	config.MomentoProxy = false
	_, handler = trackingServer(t, config, nil)
	if got := getPage(handler, "/momento/tracker.js").Code; got != http.StatusNotFound {
		t.Fatalf("proxy stayed open with momento_proxy off: %d", got)
	}
}

func TestTrackingViolationAllowanceMatchesDirectivePolicy(t *testing.T) {
	for _, tc := range []struct {
		name, origin, directive, policyDirective, source string
		allowed                                          bool
	}{
		{"connect-only origin cannot load scripts", "https://analytics.google.com", "script-src", "script-src", "https://analytics.google.com", false},
		{"script element uses script policy", "https://analytics.google.com", "script-src-elem", "script-src", "https://analytics.google.com", false},
		{"script origin allows elements", "https://www.googletagmanager.com", "script-src-elem", "script-src", "https://www.googletagmanager.com", true},
		{"connection remains allowed", "https://analytics.google.com", "connect-src", "connect-src", "https://analytics.google.com", true},
		{"image remains allowed", "https://www.googletagmanager.com", "img-src", "img-src", "https://www.googletagmanager.com", true},
		{"wildcard only allows connections", "https://region1.google-analytics.com", "img-src", "img-src", "https://*.google-analytics.com", false},
		{"wildcard connection remains allowed", "https://region1.google-analytics.com", "connect-src", "connect-src", "https://*.google-analytics.com", true},
		{"unconfigured directive remains blocked", "https://www.googletagmanager.com", "frame-src", "default-src", "https://www.googletagmanager.com", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			config := tracking.ReadConfig(map[string]any{"enabled": true, "provider": "ga4", "measurement_id": "G-1"})
			server, handler := trackingServer(t, config, nil)
			page := getPage(handler, "/dashboard")
			if page.Code != http.StatusOK {
				t.Fatalf("page status=%d", page.Code)
			}
			var sources []string
			for _, directive := range strings.Split(page.Header().Get("Content-Security-Policy"), ";") {
				fields := strings.Fields(directive)
				if len(fields) > 0 && fields[0] == tc.policyDirective {
					sources = fields[1:]
				}
			}
			found := false
			for _, source := range sources {
				if source == tc.source {
					found = true
				}
			}
			if found != tc.allowed {
				t.Fatalf("unexpected actual policy: %v", sources)
			}
			report := fmt.Sprintf(`{"csp-report":{"blocked-uri":%q,"effective-directive":%q,"document-uri":"https://jikim.example/dashboard"}}`, tc.origin+"/resource", tc.directive)
			response := httptest.NewRecorder()
			handler.ServeHTTP(response, httptest.NewRequest(http.MethodPost, cspReportPath, strings.NewReader(report)))
			if response.Code != http.StatusNoContent {
				t.Fatalf("report status=%d", response.Code)
			}
			server.sessionResolver = func(context.Context, string) (model.Session, error) {
				return model.Session{User: model.User{ID: "u1", Role: "admin"}}, nil
			}
			response = httptest.NewRecorder()
			handler.ServeHTTP(response, tokenRequest(http.MethodGet, "/api/v1/tracking/violations"))
			var result struct {
				Data []tracking.Violation `json:"data"`
			}
			if response.Code != http.StatusOK {
				t.Fatalf("list status=%d", response.Code)
			}
			if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
				t.Fatal(err)
			}
			if len(result.Data) != 1 {
				t.Fatalf("violations=%+v", result.Data)
			}
			if result.Data[0].Allowed != tc.allowed {
				t.Fatalf("directive=%s origin=%s allowed=%v, want %v", tc.directive, tc.origin, result.Data[0].Allowed, tc.allowed)
			}
		})
	}
}
package httpapi

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
)

const maxJSONBody = 2 << 20

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeData(w http.ResponseWriter, status int, value any) {
	writeJSON(w, status, map[string]any{"data": value})
}

func writeError(w http.ResponseWriter, r *http.Request, status int, code, message string) {
	writeJSON(w, status, map[string]any{"error": map[string]any{
		"code": code, "message": message, "request_id": requestIDFrom(r),
	}})
}

func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
	r.Body = http.MaxBytesReader(w, r.Body, maxJSONBody)
	decoder := json.NewDecoder(r.Body)
	decoder.UseNumber()
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		writeError(w, r, http.StatusBadRequest, "invalid_json", "JSON 요청 본문이 올바르지 않습니다")
		return false
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		writeError(w, r, http.StatusBadRequest, "invalid_json", "JSON 본문은 하나만 허용됩니다")
		return false
	}
	return true
}

func parsePage(r *http.Request) (int, int) {
	limit, offset := 50, 0
	if value := r.URL.Query().Get("limit"); value != "" {
		_, _ = fmtSscanf(value, &limit)
	}
	if value := r.URL.Query().Get("offset"); value != "" {
		_, _ = fmtSscanf(value, &offset)
	}
	return limit, offset
}

func fmtSscanf(value string, dst *int) (int, error) {
	var n int
	for _, c := range value {
		if c < '0' || c > '9' {
			return 0, errors.New("number")
		}
		n = n*10 + int(c-'0')
	}
	*dst = n
	return 1, nil
}

// Package tracking renders the visitor tracking snippet an administrator
// configured and the content security policy sources it needs.
//
// jikim ships with script-src 'self', so a pasted snippet would be refused by
// the browser without a word to the administrator. This package produces both
// halves of the answer — the markup to inject and the policy additions — with
// a per-request nonce so the inline code runs without loosening the policy for
// anything else.
package tracking

import (
	"fmt"
	"html"
	"net/url"
	"strings"
)

const (
	ProviderNone    = "none"
	ProviderMomento = "momento"
	ProviderGA4     = "ga4"
	ProviderGTM     = "gtm"
	ProviderMatomo  = "matomo"
	ProviderCustom  = "custom"

	// MaxSnippetBytes bounds a pasted snippet. A tracker loader is a few
	// hundred bytes; anything larger is a sign the wrong thing was pasted.
	MaxSnippetBytes = 8 * 1024

	// MomentoProxyPrefix is the same-origin path the server forwards to the
	// Momento collector, so the browser never talks to another origin.
	MomentoProxyPrefix = "/momento"
)

var Providers = []string{ProviderNone, ProviderMomento, ProviderGA4, ProviderGTM, ProviderMatomo, ProviderCustom}

type Config struct {
	Enabled            bool
	Provider           string
	MomentoURL         string
	MomentoSiteID      string
	MomentoEnvironment string
	MomentoProxy       bool
	MeasurementID      string
	MatomoURL          string
	MatomoSiteID       string
	CustomSnippet      string
	AllowedHosts       string
	IncludeAdmin       bool
	Placement          string
	AllowInsecureHTTP  bool
}

// ReadConfig maps the stored `tracking` setting onto the configuration. A
// missing or mistyped value falls back to the default, which is always the
// switched-off one.
func ReadConfig(values map[string]any) Config {
	config := Config{Provider: ProviderNone, Placement: "head", MomentoProxy: true, MomentoEnvironment: "prd"}
	config.Enabled, _ = values["enabled"].(bool)
	config.Provider = strings.ToLower(stringValue(values, "provider", ProviderNone))
	config.MomentoURL = stringValue(values, "momento_url", "")
	config.MomentoSiteID = stringValue(values, "momento_site_id", "")
	config.MomentoEnvironment = stringValue(values, "momento_environment", "prd")
	if raw, ok := values["momento_proxy"].(bool); ok {
		config.MomentoProxy = raw
	}
	config.MeasurementID = stringValue(values, "measurement_id", "")
	config.MatomoURL = stringValue(values, "matomo_url", "")
	config.MatomoSiteID = stringValue(values, "matomo_site_id", "")
	config.CustomSnippet, _ = values["custom_snippet"].(string)
	config.AllowedHosts = stringValue(values, "allowed_hosts", "")
	config.IncludeAdmin, _ = values["include_admin"].(bool)
	config.Placement = strings.ToLower(stringValue(values, "placement", "head"))
	if config.Placement != "body" {
		config.Placement = "head"
	}
	config.AllowInsecureHTTP, _ = values["allow_insecure_http"].(bool)
	return config
}

// Active reports whether the page at path should carry the snippet. The
// administrative screens are left out unless asked for, because console
// traffic is rarely the visitor data anybody wants to measure.
func (c Config) Active(path string) bool {
	if !c.Enabled || c.Provider == ProviderNone || c.Provider == "" {
		return false
	}
	if !c.IncludeAdmin && AdminPath(path) {
		return false
	}
	return strings.TrimSpace(c.Snippet("")) != ""
}

// AdminPath reports the screens only an administrator opens.
func AdminPath(path string) bool {
	return strings.HasPrefix(path, "/admin/") || path == "/admin" ||
		strings.HasPrefix(path, "/infrastructure/") || path == "/infrastructure" ||
		path == "/access/authentication"
}

// ReportingActive reports whether the policy handed to any browser carries the
// report-uri, which is what makes an arriving report worth keeping. It is
// Active without the per-path rule on purpose: a report names the page that was
// refused, and that name comes from whoever posted it, so it cannot gate
// anything — and an install tracking only the administrative screens still has
// to hear what those screens refused.
func (c Config) ReportingActive() bool {
	if !c.Enabled || c.Provider == ProviderNone || c.Provider == "" {
		return false
	}
	return strings.TrimSpace(c.Snippet("")) != ""
}

// ProxyActive reports whether /momento/* should be forwarded to the collector.
func (c Config) ProxyActive() bool {
	return c.Enabled && c.Provider == ProviderMomento && c.MomentoProxy && strings.TrimSpace(c.MomentoURL) != ""
}

// Validate reports what is missing or wrong for the chosen provider. The
// snippet size and the provider name are checked even while tracking is off,
// so a bad value is refused at save time rather than discovered at switch-on.
func (c Config) Validate() error {
	if !validProvider(c.Provider) {
		return fmt.Errorf("provider는 %s 중 하나여야 합니다", strings.Join(Providers, ", "))
	}
	if len(c.CustomSnippet) > MaxSnippetBytes {
		return fmt.Errorf("custom_snippet은 %d바이트를 넘을 수 없습니다", MaxSnippetBytes)
	}
	for _, field := range []struct{ name, value string }{{"momento_url", c.MomentoURL}, {"matomo_url", c.MatomoURL}} {
		if strings.TrimSpace(field.value) == "" {
			continue
		}
		if err := validateCollectorURL(field.value, c.AllowInsecureHTTP); err != nil {
			return fmt.Errorf("%s: %v", field.name, err)
		}
	}
	if !c.Enabled {
		return nil
	}
	switch c.Provider {
// withNonce adds the nonce to every script tag that does not already carry
// one, which is what lets a pasted snippet run under a strict policy unchanged.
func withNonce(snippet, nonce string) string {
	if nonce == "" || snippet == "" {
		return snippet
	}
	var builder strings.Builder
	remaining := snippet
	for {
		index := strings.Index(strings.ToLower(remaining), "<script")
		if index < 0 {
			builder.WriteString(remaining)
			return builder.String()
		}
		end := index + len("<script")
		builder.WriteString(remaining[:end])
		tag := remaining[end:]
		if closing := strings.Index(tag, ">"); closing >= 0 {
			tag = tag[:closing]
		}
		if !strings.Contains(strings.ToLower(tag), "nonce=") {
			builder.WriteString(` nonce="` + html.EscapeString(nonce) + `"`)
		}
		remaining = remaining[end:]
	}
}

// Inject places the snippet just before the closing tag the placement names,
// falling back to the end of the document when that tag is missing.
func Inject(page []byte, snippet, placement string) []byte {
	marker := "</head>"
	if placement == "body" {
		marker = "</body>"
	}
	text := string(page)
	index := strings.LastIndex(strings.ToLower(text), marker)
	if index < 0 {
		return []byte(text + "\n" + snippet + "\n")
	}
	return []byte(text[:index] + snippet + "\n" + text[index:])
}

// PolicySources lists the extra origins the snippet needs, derived from the
// provider so the common setups need no policy knowledge at all.
func (c Config) PolicySources() (scripts []string, connects []string, images []string) {
	add := func(origin string) {
		scripts = append(scripts, origin)
		connects = append(connects, origin)
		images = append(images, origin)
	}
	switch c.Provider {
	case ProviderMomento:
		if !c.MomentoProxy {
			if origin := originOf(c.MomentoURL); origin != "" {
				add(origin)
			}
		}
	case ProviderGA4, ProviderGTM:
		scripts = append(scripts, "https://www.googletagmanager.com")
		connects = append(connects, "https://www.google-analytics.com", "https://analytics.google.com", "https://*.google-analytics.com")
		images = append(images, "https://www.google-analytics.com", "https://www.googletagmanager.com")
	case ProviderMatomo:
		if origin := originOf(c.MatomoURL); origin != "" {
			add(origin)
		}
	case ProviderCustom:
		// A pasted snippet names the addresses it loads and reports to, so
		// those origins are allowed without anybody reading a policy error.
		for _, origin := range SnippetOrigins(c.CustomSnippet) {
			add(origin)
		}
	}
	for _, host := range SplitHosts(c.AllowedHosts) {
		add(host)
	}
	return scripts, connects, images
}

// SplitHosts reads the comma, space or newline separated allow list.
func SplitHosts(raw string) []string {
	hosts := make([]string, 0, 2)
	for _, host := range strings.FieldsFunc(raw, func(letter rune) bool {
		return letter == ',' || letter == ' ' || letter == '\n' || letter == '\r' || letter == '\t'
	}) {
		if trimmed := strings.TrimSpace(host); trimmed != "" {
			hosts = append(hosts, trimmed)
		}
	}
	return hosts
