		return model.User{}, false, mapError(err)
	}
	if err := s.ensureUserKeyTx(ctx, tx, user.ID, user.PersonalKeyVersion); err != nil {
		return model.User{}, false, err
	}
	if err := tx.Commit(ctx); err != nil {
		return model.User{}, false, err
	}
	return user, created, nil
}

